+        #region Support methods
+        private void SetDefault()
+        {
+            if (dtmFromDate.SelectedDate == null)
+            {
+                dtmFromDate.SelectedDate = DateTime.Now;
+                dtmToDate.SelectedDate = DateTime.Now.AddDays(30);
+            }
