+        private bool IsValidData(bool isShowMsg)
+        {
+            if (uClass.ClassID == null && !uClass.IsRegulation43)
+            {
+                if (isShowMsg)
+                    MsgBox.ShowWarning("Bạn phải chọn lớp học!");
+                return false;
+            }
+            if (dtmFromDate.SelectedDate == null)
