+                string strColumn = "Value_" + drwDate["DateIndex"].ToString();
+                foreach (DataRow drw in dtbData.Rows)
+                    drw[strColumn] = 0;
+            }
+        }
+        private void FillCheckingData()
+        {
+            foreach (DataRow drwChecking in dtbStudentChecking.Rows)
+            {
+                int? intNoPermissionQuantity = Libs.MyConvert.ToInt32(drwChecking[SIM_SubjectChecking.C_NoPermissionQuantity]);
+                int? intPermissionQuantity = Libs.MyConvert.ToInt32(drwChecking[SIM_SubjectChecking.C_PermissionQuantity]);
+                int intValue = (intNoPermissionQuantity == null ? 0 : intNoPermissionQuantity.Value) + (intPermissionQuantity == null ? 0 : intPermissionQuantity.Value);
+                if (intValue <= 0 || drwChecking["Date"] == DBNull.Value)
+                    continue;
+                DataRow[] rowDates = dtbDateSchedule.Select("Date='" + Convert.ToDateTime(drwChecking["Date"]).ToString("yyyy-MM-dd") + "'");
+                if (rowDates.Length == 0)
+                    continue;
+                string strStudentID = drwChecking["StudentID"].ToString().Replace("'", "''");
+                DataRow[] rows = dtbData.Select("StudentID='" + strStudentID + "'");
+                if (rows.Length > 0)
+                    rows[0]["Value_" + rowDates[0]["DateIndex"].ToString()] = intValue;
+            }
+        }
+        private void TotalRow(DataRow drw)
+        {
+            int intTotal = 0;
+            foreach (DataRow drwDate in dtbDateSchedule.Rows)
+            {
+                int? intValue = Libs.MyConvert.ToInt32(drw["Value_" + drwDate["DateIndex"].ToString()]);
+                if (intValue != null)
+                    intTotal += intValue.Value;
+            }
+            drw["TotalOff"] = intTotal;
+        }
+        private string HtmlEncode(object value)
+        {
+            if (value == null || value == DBNull.Value)
+                return "";
+            return HttpUtility.HtmlEncode(value.ToString());
+        }
+        private string DayOfWeekString(DateTime dtmDate)
+        {
+            switch (dtmDate.DayOfWeek)
+            {
+                case DayOfWeek.Monday:
+                    return "T2";
+                case DayOfWeek.Tuesday:
+                    return "T3";
+                case DayOfWeek.Wednesday:
+                    return "T4";
+                case DayOfWeek.Thursday:
+                    return "T5";
+                case DayOfWeek.Friday:
+                    return "T6";
+                case DayOfWeek.Saturday:
+                    return "T7";
+                case DayOfWeek.Sunday:
+                    return "CN";
+            }
+            return "";
+        }
+        private string AttendanceValueToString(object value)
+        {
+            if (value == null || value == DBNull.Value || value.ToString() == "")
+                return "";
+            int? intValue = Libs.MyConvert.ToInt32(value);
